function elapsed(start,end=today()){if(!start)return null;return Math.max(0,Math.round((new Date(end+'T12:00:00')-new Date(start+'T12:00:00'))/86400000));}
function economics(o){
 const p=purchase(o.purchaseId),info=p?purchaseInfo(p):null,product=o.items.reduce((sum,i)=>sum+itemCostTotal(i),0),duty=p?null:dutyAmount(o),shared=p?allocatedCost(p,o.id):0;
 const missing=o.items.filter(i=>i.cost==null).map(i=>`inkoop ${i.description}`);if(!totals(o).priceKnown)missing.push('verkoopprijs van de producten');
 if(o.shippingActual==null)missing.push('verzending Nederland → klant');if(o.extraCosts==null)missing.push('overige orderkosten');
 if(p){missing.push(...info.missingShared);if(p.allocation==='cost'&&!info.goodsKnown)missing.push('inkoopwaarden voor de verdeling');}else if(duty==null)missing.push('invoerrechten');
 const cost=product+(o.shippingActual??0)+(o.extraCosts??0)+(duty??0)+shared,revenue=totals(o).net,estimated=(p?p.dutyMode:o.dutyMode)==='calculate',known=missing.length===0;
 return {known,missing:[...new Set(missing)],estimated,provisional:!known||estimated||!o.shippingKnown,product,cost,shared,duty,profit:revenue-cost,margin:revenue?((revenue-cost)/revenue*100):0};
}
function paidDate(o){const t=totals(o);if(!t.priceKnown||t.balance>0||t.total<=0)return '';let sum=0;for(const p of state.payments.filter(p=>p.orderId===o.id).sort((a,b)=>a.date.localeCompare(b.date))){sum+=p.amount;if(sum>=t.total)return p.date;}return '';}
function compactWorkflow(o){const groups=[['Ontwerp','Ontwerp maken','Ontwerp goedgekeurd'],['Offerte','Offerte verstuurd','Offerte verstuurd'],['Betaling','Wachten op betaling','Wachten op betaling'],['Inkoop & productie','Productie vrijgegeven','Binnen in Nederland'],['Levering','Verzonden','Afgerond']],index=stages.indexOf(o.stage);return `<div class="phase-track">${groups.map(([name,first,last],n)=>{const start=stages.indexOf(first),end=stages.indexOf(last);return `<div class="phase ${index>end?'passed':''} ${index>=start&&index<=end?'active':''}"><span class="phase-number">${n+1}</span><span>${name}</span></div>`;}).join('')}</div>`;}

