   newPurchase=fd.get('purchaseId')==='__new__'?{id:uid(),name:fd.get('newPurchaseName').trim(),supplier:fd.get('newPurchaseSupplier').trim(),allocation:'equal',status:'Verzamelen',freight:null,extraCosts:null,dutyMode:'fixed',dutyAmount:null}:null;if(newPurchase&&!newPurchase.name)throw Error('Geef de nieuwe inkoopbestelling een naam.');
   data={quoteOutcome:fd.get('quoteOutcome')||'',customerId:newCustomer?.id||chosen,sourceNumber:fd.get('sourceNumber').trim(),date:fd.get('date'),expectedDate:fd.get('expectedDate'),vat,shippingKnown:shipping!=='',shippingCharge:shipping===''?0:cents(shipping),purchaseId:newPurchase?.id||fd.get('purchaseId'),notes:fd.get('notes'),items,packagePrice:readPackagePrice(fd),...readLeadTime(fd)};
