 const amount=k=>fd.get(k)===''?null:cents(fd.get(k)),items=readItems(),costs={shippingActual:amount('shippingActual'),extraCosts:amount('extraCosts')};
 items.forEach(i=>{i.cost=amount('aiCost_'+i.id);});if([...Object.values(costs),...items.map(i=>i.cost)].some(n=>n!=null&&(!Number.isSafeInteger(n)||n<0)))throw Error('Controleer de orderkosten.');
 let purchaseId=fd.get('purchaseId');if(purchaseId==='__new__'){const name=fd.get('newPurchaseName').trim();if(!name)throw Error('Geef de inkoopbestelling een naam.');const p={id:uid(),name,supplier:fd.get('newPurchaseSupplier').trim()||fd.get('supplier').trim(),allocation:'equal',status:'Verzamelen',freight:null,extraCosts:null,dutyMode:'fixed',dutyAmount:null};next.purchases.push(p);purchaseId=p.id;}else if(purchaseId&&!next.purchases.some(p=>p.id===purchaseId))throw Error('De inkoopbestelling bestaat niet.');
