function purchase(id){return state.purchases.find(p=>p.id===id);}
function supplierItems(o){return o.items.filter(i=>i.productionSource!=='local');}
function purchaseOrders(p){return state.orders.filter(o=>o.purchaseId===p.id&&supplierItems(o).length);}
function dutyAmount(record){return record.dutyMode==='calculate'?(record.dutyBase==null||record.dutyRate==null?null:Math.round(record.dutyBase*record.dutyRate/100)):(record.dutyAmount??null);}
function dutyFields(p){return `<div class="fields"><label>Invoerrechten<select name="dutyMode"><option value="fixed" ${p.dutyMode!=='calculate'?'selected':''}>Werkelijk bedrag invullen</option><option value="calculate" ${p.dutyMode==='calculate'?'selected':''}>Berekenen uit grondslag en percentage</option></select></label>${field('dutyAmount','Werkelijke invoerrechten (€)',p.dutyAmount==null?'':p.dutyAmount/100,'number','min="0" step="0.01"')}${field('dutyBase','Grondslag invoerrechten (€)',p.dutyBase==null?'':p.dutyBase/100,'number','min="0" step="0.01"')}${field('dutyRate','Percentage invoerrechten (%)',p.dutyRate??'','number','min="0" max="100" step="0.01"')}</div><p class="muted">Vul je eigen grondslag en tarief in. Dit is een rekenhulp; er wordt geen tarief automatisch gekozen. Het berekende bedrag is een schatting.</p><p id="duty-preview" class="notice"></p>`;}
function readDuty(fd){const money=k=>fd.get(k)==null||fd.get(k)===''?null:cents(fd.get(k));const d={dutyMode:fd.get('dutyMode'),dutyAmount:money('dutyAmount'),dutyBase:money('dutyBase'),dutyRate:fd.get('dutyRate')==null||fd.get('dutyRate')===''?null:Number(fd.get('dutyRate'))};if([d.dutyAmount,d.dutyBase].some(v=>v!==null&&(!Number.isSafeInteger(v)||v<0))||d.dutyRate!==null&&(!Number.isFinite(d.dutyRate)||d.dutyRate<0||d.dutyRate>100))throw Error('Controleer invoerrechten.');return d;}
function updateDutyPreview(){const form=$('#dialog form');if(!form?.querySelector('[name=dutyMode]'))return;const calculated=form.querySelector('[name=dutyMode]').value==='calculate';for(const name of ['dutyAmount','dutyBase','dutyRate']){const input=form.querySelector(`[name=${name}]`),show=name==='dutyAmount'?!calculated:calculated;input.disabled=!show;input.closest('label').hidden=!show;}try{const d=readDuty(new FormData(form)),value=dutyAmount(d);$('#duty-preview').textContent=value==null?'Invoerrechten nog onbekend':`Invoerrechten: ${euro(value)}${d.dutyMode==='calculate'?' (berekende schatting)':''}`;}catch{$('#duty-preview').textContent='Controleer de ingevoerde bedragen.';}}
function purchaseInfo(p){const orders=purchaseOrders(p),goods=orders.reduce((sum,o)=>sum+supplierItems(o).reduce((a,i)=>a+itemCostTotal(i),0),0),goodsKnown=orders.every(o=>supplierItems(o).every(i=>i.cost!=null)),duty=dutyAmount(p),missingShared=[];if(p.freight==null)missingShared.push('transport Turkije → Nederland');if(duty==null)missingShared.push('invoerrechten inkoopbestelling');if(p.extraCosts==null)missingShared.push('inklaring / overige inkoopkosten');return {orders,goods,goodsKnown,duty,missingShared,shared:(p.freight??0)+(duty??0)+(p.extraCosts??0),sharedKnown:missingShared.length===0};}
function allocationWeight(o,method){const items=supplierItems(o);if(!method||method==='equal')return 1;if(method==='quantity')return items.reduce((s,i)=>s+i.quantity,0);if(method==='cost')return items.reduce((s,i)=>s+itemCostTotal(i),0);return items.reduce((s,i)=>s+i.quantity*(i.width||0)*(i.height||0),0);}
function allocatedAmount(p,orderId,amount){const rows=purchaseOrders(p).map(o=>({id:o.id,weight:allocationWeight(o,p.allocation),amount:0}));if(!rows.length||!amount)return 0;const totalWeight=rows.reduce((sum,r)=>sum+r.weight,0);if(!totalWeight)rows.forEach(r=>r.weight=1);const sum=totalWeight||rows.length;rows.forEach(r=>{const raw=amount*r.weight/sum;r.amount=Math.floor(raw);r.remainder=raw-r.amount;});const remainder=amount-rows.reduce((sum,r)=>sum+r.amount,0);[...rows].sort((a,b)=>b.remainder-a.remainder||a.id.localeCompare(b.id)).slice(0,remainder).forEach(r=>r.amount++);return rows.find(r=>r.id===orderId)?.amount||0;}
function allocatedCost(p,orderId){return [p.freight??0,dutyAmount(p)??0,p.extraCosts??0].reduce((sum,amount)=>sum+allocatedAmount(p,orderId,amount),0);}
function freightShareDescription(p,orderId){const n=purchaseOrders(p).length,amount=allocatedAmount(p,orderId,p.freight??0);return `<p class="form-help">Transportaandeel: ${euro(p.freight??0)}${!p.allocation||p.allocation==='equal'?` ÷ ${n} klantorder${n===1?'':'s'}`:' verdeeld volgens de gekozen methode'} = <strong>${euro(amount)}</strong>${p.freight==null?' · transport nog niet ingevuld':''}.</p>`;}
function purchaseSelect(selected,allowNew=true){return `<label>Inkoopbestelling bij leverancier<select name="purchaseId"><option value="">Nog niet koppelen</option>${state.purchases.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${esc(p.supplier)}</option>`).join('')}${allowNew?'<option value="__new__">+ Nieuwe inkoopbestelling maken</option>':''}</select></label>${allowNew?`<div class="wide create-purchase-box" data-inline-purchase hidden><h3>Nieuwe inkoopbestelling</h3><div class="fields">${field('newPurchaseName','Naam / referentie',`Turkije bestelling ${state.purchases.length+1}`)}${field('newPurchaseSupplier','Leverancier')}</div><p>Je order wordt meteen gekoppeld. Transport, invoerrechten en andere klantorders kun je daarna in de inkoopbestelling toevoegen.</p></div>`:''}`;}
