 if(tab==='costs')content=`<div class="order-grid"><div><section class="order-surface"><div class="section-heading"><div><h2>Gezamenlijke kosten</h2><p>Eén transport voor producten uit meerdere facturen.</p></div>${button('edit-purchase','Kosten aanpassen',id)}</div>${orderSummaryRows([['Transport Turkije → Nederland',p.freight==null?'Nog onbekend':euro(p.freight)],['Invoerrechten',x.duty==null?'Nog onbekend':euro(x.duty)],['Inklaring / overige kosten',p.extraCosts==null?'Nog onbekend':euro(p.extraCosts)],['Inkoop producten',euro(x.goods)+(x.goodsKnown?'':' (voorlopig)')],['Totale bekende kostprijs',euro(x.goods+x.shared)]])}<p class="form-help">Bedragen excl. btw. ${x.missingShared.length?'Nog niet meegenomen: '+esc(x.missingShared.join(', '))+'.':''} Leveranciersbetalingen worden niet opnieuw als kosten opgeteld.</p></section><section class="order-surface"><div class="section-heading"><h2>Leverancier</h2>${button('edit-purchase','Bewerken',id)}</div><strong>${esc(p.supplier)}</strong><p>${esc(p.supplierContact||'Contactpersoon nog niet ingevuld')}</p><p>${esc(p.supplierEmail||'')} ${esc(p.supplierPhone||'')}</p><address class="notes">${esc(p.supplierAddress||'')}</address><p class="form-help">Leveringsconditie: ${esc(p.deliveryTerms||'nog niet ingevuld')}</p></section></div><section class="order-surface"><div class="section-heading"><h2>Planning van de zending</h2>${button('edit-purchase','Aanpassen',id)}</div>${badge(p.status,'blue')}<p>${['Onderweg','Binnen in Nederland'].includes(p.status)||p.shippedDate?'Verzonden door leverancier':'Nog niet verzonden'}</p>${orderSummaryRows([['Besteld bij leverancier',date(p.orderedDate)],['Verzonden naar Nederland',date(p.shippedDate)],['Verwachte aankomst Nederland',date(p.expectedDate)],['Werkelijke aankomst',date(p.arrivedDate)]])}<p class="form-help">De factuurdatum en de betaaldatum staan per document. Nieuwe producten kunnen toegevoegd worden zolang de zending nog niet vertrokken is.</p></section></div>`;
