 return `<div class="item supplier-line"><div class="fields"><label class="wide">Product / klantorder<select name="itemId"><option value="">Geen product koppelen (kosten apart invullen)</option>${choices.map(({o,i})=>`<option value="${i.id}" ${i.id===line.itemId?'selected':''}>${esc(customer(o.customerId)?.company)} · ${esc(i.description)} · ${itemDimensions(i)}</option>`).join('')}</select></label>${field('description','Omschrijving op document',line.description,'text','required')}${field('quantity','Aantal eenheden',line.quantity,'number','required min="1" step="1"')}<label>Eenheid<select name="unit"><option value="piece" ${line.unit!=='pair'?'selected':''}>Stuk</option><option value="pair" ${line.unit==='pair'?'selected':''}>Paar (2 stuks)</option></select></label>${field('price','Inkoopprijs per eenheid (€)',(line.price??0)/100,'number','required min="0" step="0.01"')}</div><p>${button('remove-supplier-line','Regel weglaten')}</p></div>`;
