function purchaseForm(id,originOrderId){
 const p=purchase(id)||{allocation:'equal',status:'Verzamelen',supplier:order(originOrderId)?.supplier||''};
 const available=state.orders.filter(o=>o.purchaseId===id||o.id===originOrderId||!o.archived&&!o.purchaseId);
 openForm(id?'Inkoopbestelling bewerken':'Nieuwe inkoopbestelling',`<section class="form-section"><h3>Bestelling bij leverancier</h3><div class="fields">${field('name','Naam / referentie',p.name||`Turkije bestelling ${state.purchases.length+1}`,'text','required')}${field('supplier','Leverancier',p.supplier)}<label>Status<select name="status">${options(['Verzamelen','Besteld','In productie','Onderweg','Binnen in Nederland'],p.status)}</select></label>${field('orderedDate','Besteld op',p.orderedDate,'date')}${field('supplierContact','Contactpersoon leverancier',p.supplierContact)}${field('supplierEmail','E-mail leverancier',p.supplierEmail,'email')}${field('supplierPhone','Telefoon leverancier',p.supplierPhone)}${field('deliveryTerms','Leveringsconditie (bijv. FCA)',p.deliveryTerms)}${area('supplierAddress','Adres leverancier',p.supplierAddress)}</div></section><section class="form-section"><h3>Klantorders in deze bestelling</h3><div class="purchase-choices">${available.map(o=>`<label class="check-row"><input type="checkbox" name="orderIds" value="${o.id}" ${o.purchaseId===id&&id||o.id===originOrderId?'checked':''}><span>#${esc(o.sourceNumber||o.number)} · ${esc(customer(o.customerId)?.company)}${o.archived?' (gearchiveerd)':''}</span></label>`).join('')||'<p class="muted">Er zijn nog geen beschikbare klantorders. Je kunt ze later koppelen.</p>'}</div><p class="form-help">Per klantorder koppelen we de producten via de leverancier. Producten met productieplek “Lokaal in Nederland” vallen hierbuiten.</p></section><details class="form-details" ${id?'open':''}><summary>Gezamenlijke kosten & verdeling</summary><div class="fields form-spaced">${field('freight','Transport Turkije → Nederland excl. btw (€)',p.freight==null?'':p.freight/100,'number','min="0" step="0.01"')}${field('extraCosts','Inklaring / overige gezamenlijke kosten (€)',p.extraCosts==null?'':p.extraCosts/100,'number','min="0" step="0.01"')}<label>Verdeling over klantorders<select name="allocation"><option value="equal" ${!p.allocation||p.allocation==='equal'?'selected':''}>Gelijk delen over klantorders</option><option value="area" ${p.allocation==='area'?'selected':''}>Naar totale spatlapoppervlakte</option><option value="quantity" ${p.allocation==='quantity'?'selected':''}>Naar aantal stuks</option><option value="cost" ${p.allocation==='cost'?'selected':''}>Naar inkoopwaarde</option></select></label></div><p class="form-help">Leeg betekent nog onbekend. De ingevulde kosten worden direct meegenomen; de rest kun je later aanvullen.</p><h3>Invoerrechten</h3>${dutyFields(p)}</details><details class="form-details"><summary>Planning van de zending</summary><div class="fields form-spaced">${field('expectedDate','Verwachte aankomst Nederland',p.expectedDate,'date')}${field('arrivedDate','Werkelijke aankomst Nederland',p.arrivedDate,'date')}${field('shippedDate','Verzonden door leverancier',p.shippedDate,'date')}</div></details><p class="form-help">Een statuswijziging geldt voor deze inkoopbestelling. Klantorders houd je afzonderlijk bij; ontvangst van geld wordt nooit uit een status afgeleid.</p>`,async fd=>{
 const amount=k=>fd.get(k)===''?null:cents(fd.get(k));for(const k of ['freight','extraCosts'])if(amount(k)!==null&&(!Number.isSafeInteger(amount(k))||amount(k)<0))throw Error('Controleer de kostenbedragen.');
 const values={name:fd.get('name').trim(),supplier:fd.get('supplier').trim(),supplierContact:fd.get('supplierContact').trim(),supplierEmail:fd.get('supplierEmail').trim(),supplierPhone:fd.get('supplierPhone').trim(),supplierAddress:fd.get('supplierAddress').trim(),deliveryTerms:fd.get('deliveryTerms').trim(),status:fd.get('status'),orderedDate:fd.get('orderedDate'),expectedDate:fd.get('expectedDate'),arrivedDate:fd.get('arrivedDate'),freight:amount('freight'),extraCosts:amount('extraCosts'),shippedDate:fd.get('shippedDate'),allocation:fd.get('allocation'),...readDuty(fd)};if(!values.name)throw Error('Vul een naam in.');
 // Preserve an existing date; only timestamp the selected real-world step on a status change.
 if(values.status!==p.status){if(values.status==='Besteld'&&!values.orderedDate)values.orderedDate=today();if(values.status==='Onderweg'&&!values.shippedDate)values.shippedDate=today();if(values.status==='Binnen in Nederland'&&!values.arrivedDate)values.arrivedDate=today();}
 const record=id?p:{id:uid()};Object.assign(record,values);if(!id)state.purchases.push(record);
 const selected=new Set(fd.getAll('orderIds'));if(originOrderId)selected.add(originOrderId);for(const o of state.orders){if(selected.has(o.id))o.purchaseId=record.id;else if(o.purchaseId===record.id)o.purchaseId='';}
 await save('Inkoopbestelling opgeslagen');location.hash=originOrderId?`orders/${originOrderId}`:`purchases/${record.id}`;
 });updateDutyPreview();
}
