function orderTimeline(o){const p=purchase(o.purchaseId),index=stages.indexOf(o.stage);const entries=[['Ontwerp maken','date',0],['Wachten op goedkeuring','designSentDate',1],['Ontwerp goedgekeurd','approvedDate',2],['Offerte verstuurd','quoteSentDate',3],['Wachten op betaling','paymentRequestedDate',4],['Productie vrijgegeven','productionReleasedDate',5],['Besteld bij leverancier','supplierOrderedDate',6],['In productie','productionDate',7],['Onderweg naar Nederland','transitDate',8],['Binnen in Nederland','arrivedDate',9],['Verzonden','shippedDate',10],['Afgerond','deliveredDate',11]];return `<ol class="timeline">${entries.map(([name,key,step])=>{const value=o[key]||(key==='supplierOrderedDate'?p?.orderedDate:key==='arrivedDate'?p?.arrivedDate:'');const current=step===index,passed=step<index;return `<li class="${value||passed?'done':''} ${current?'current':''}"><strong>${name}${current?' · nu':''}</strong><span>${value?date(value):current?'Huidige stap':passed?'Gepasseerd · datum onbekend':'Nog te doen'}</span></li>`;}).join('')}</ol>`;}
function changeOrderStage(o,stage){if(stage===o.stage)return;o.stage=stage;o.statusHistory??=[];o.statusHistory.push({stage,date:today(),time:new Date().toISOString()});const key={'Wachten op goedkeuring':'designSentDate','Ontwerp goedgekeurd':'approvedDate','Offerte verstuurd':'quoteSentDate','Wachten op betaling':'paymentRequestedDate','Productie vrijgegeven':'productionReleasedDate','Besteld bij leverancier':'supplierOrderedDate','In productie':'productionDate','Onderweg naar Nederland':'transitDate','Binnen in Nederland':'arrivedDate','Verzonden':'shippedDate','Afgerond':'deliveredDate'}[stage];if(key&&!o[key])o[key]=today();}
