function registerOrderProgress(o,stage,quoteOnly=false){
 const keys={'Wachten op goedkeuring':'designSentDate','Ontwerp goedgekeurd':'approvedDate','Offerte verstuurd':'quoteSentDate','Wachten op betaling':'paymentRequestedDate','Productie vrijgegeven':'productionReleasedDate','Besteld bij leverancier':'supplierOrderedDate','In productie':'productionDate','Onderweg naar Nederland':'transitDate','Binnen in Nederland':'arrivedDate','Verzonden':'shippedDate','Afgerond':'deliveredDate'},key=keys[stage];
 openForm('Voortgang registreren',`<p><strong>${esc(stage)}</strong></p><p class="form-help">Hier werk je bij wat er is gebeurd. Een registratie in het CRM verstuurt geen bericht aan de klant of leverancier.</p>${key?`${field('eventDate','Datum waarop dit is gebeurd',o[key]||today(),'date','required')}<label class="check-row form-spaced"><input name="dateUnknown" type="checkbox">Datum nog onbekend</label>`:''}`,async fd=>{
  const next=structuredClone(state),updated=next.orders.find(x=>x.id===o.id);
  if(!quoteOnly||stages.indexOf(updated.stage)<=stages.indexOf(stage))changeOrderStage(updated,stage);
  if(key)updated[key]=fd.has('dateUnknown')?'':fd.get('eventDate');
  next.activities.unshift({id:uid(),message:`Order #${updated.sourceNumber||updated.number}: ${stage} geregistreerd`,time:new Date().toISOString()});
  await store('state','readwrite',s=>s.put(next,'main'));state=next;render();toast('Datum en orderstatus bijgewerkt');
 });$('#dialog [type=submit]').textContent='Voortgang opslaan';
}
