function updateDeliveryDraft(form){
 const o=order(form.dataset.orderId);if(!o)return;
 const values=Object.fromEntries(new FormData(form)),saved=deliveryValues(o,customer(o.customerId));
 const dirty=['recipient','country','address','instructions'].some(key=>(values[key]||'')!==(saved[key]||''));
 if(dirty)deliveryDrafts.set(o.id,values);else deliveryDrafts.delete(o.id);
 form.querySelector('[type=submit]').disabled=!dirty;
 form.querySelector('[data-action=delivery-cancel]').hidden=!dirty;
 form.querySelector('[data-delivery-status]').textContent=dirty?'Wijzigingen nog niet opgeslagen.':'Geen onopgeslagen wijzigingen.';
 form.querySelector('[data-delivery-error]').textContent='';
}
document.addEventListener('input',e=>{const form=e.target.closest('#delivery-address-form');if(form)updateDeliveryDraft(form);});
document.addEventListener('submit',async e=>{
 const form=e.target;if(form.id!=='delivery-address-form')return;e.preventDefault();
 const o=order(form.dataset.orderId);if(!o)return;
 const fields=Object.fromEntries(new FormData(form)),previous=o.delivery;
 const activity={id:uid(),message:'Afleveradres van order bijgewerkt',time:new Date().toISOString()};
 const controls=[...form.querySelectorAll('button,input,textarea')];controls.forEach(control=>control.disabled=true);
 o.delivery={source:'custom',...Object.fromEntries(['recipient','country','address','instructions'].map(key=>[key,String(fields[key]||'').trim()]))};
 const undoCustomerSync=syncSingleOrderDelivery(o);
 try{
  // Commit before changing the card or its map, keeping failed edits available.
  await store('state','readwrite',s=>s.put({...state,activities:[activity,...state.activities]},'main'));
  state.activities.unshift(activity);
  deliveryDrafts.delete(o.id);render();toast(customerOrders(o.customerId).length===1?'Afleveradres opgeslagen bij klant en order':'Afleveradres opgeslagen voor deze order');
 }catch(error){o.delivery=previous;undoCustomerSync();controls.forEach(control=>control.disabled=false);updateDeliveryDraft(form);form.querySelector('[data-delivery-error]').textContent='Opslaan mislukt: '+error.message;}
});
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b||!['delivery-use-customer','delivery-cancel'].includes(b.dataset.action))return;
 const o=order(b.dataset.id);if(!o)return;
 if(b.dataset.action==='delivery-cancel'){deliveryDrafts.delete(o.id);if(pendingExternalRefresh)refreshExternalState();else render();return;}
 const c=customer(o.customerId),form=$('#delivery-address-form');if(!c?.shippingAddress||!form)return;
 const values=deliveryDetails({},c);for(const key of ['recipient','country','address'])form.elements[key].value=values[key]||'';
 updateDeliveryDraft(form);form.elements.address.focus();
});
window.addEventListener('beforeunload',e=>{if(deliveryDrafts.size){e.preventDefault();e.returnValue='';}});

function analyticsDateRange(){const now=today(),year=Number(now.slice(0,4));if(analyticsPeriod==='year')return {start:`${year}-01-01`,end:`${year}-12-31`};if(analyticsPeriod==='12months'){const d=new Date(now+'T12:00:00');d.setMonth(d.getMonth()-11,1);return {start:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`,end:now};}return {start:'',end:''};}
function inAnalyticsPeriod(value,range){return !!value&&(!range.start||value>=range.start)&&(!range.end||value<=range.end);}
function analyticsChart(orders,range){
 const endMonth=range.end?range.end.slice(0,7):today().slice(0,7),anchor=new Date(endMonth+'-01T12:00:00');const months=[];
 if(analyticsPeriod==='year'){for(let n=0;n<12;n++)months.push(`${today().slice(0,4)}-${String(n+1).padStart(2,'0')}`);}else{for(let n=11;n>=0;n--){const d=new Date(anchor);d.setMonth(anchor.getMonth()-n);months.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);}}
 const values=months.map(month=>orders.filter(o=>o.date?.slice(0,7)===month).reduce((s,o)=>s+totals(o).net,0)),max=Math.max(1,...values),w=900,h=240,left=55,top=20,base=195,spacing=68,bar=34;
 const ticks=[0,.5,1].map(f=>`<g><line x1="${left}" x2="880" y1="${base-f*165}" y2="${base-f*165}" stroke="#e6edf5"/><text x="${left-8}" y="${base-f*165+4}" text-anchor="end" font-size="10" fill="#7a8ca3">${Math.round(max*f/100).toLocaleString('nl-NL')}</text></g>`).join('');
 const bars=months.map((month,i)=>{const height=values[i]/max*165,x=left+13+i*spacing,label=new Date(month+'-01T12:00:00').toLocaleDateString('nl-NL',{month:'short'});return `<g><rect x="${x}" y="${base-height}" width="${bar}" height="${Math.max(values[i]>0?2:0,height)}" rx="4" fill="#4179df"><title>${month}: ${euro(values[i])} excl. btw</title></rect><text x="${x+bar/2}" y="${base+20}" font-size="11" text-anchor="middle" fill="#7a8ca3">${label}</text></g>`;}).join('');
 return `<svg class="analytics-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Orderomzet exclusief btw per maand">${ticks}${bars}</svg><p class="form-help">${analyticsPeriod==='year'?'Januari t/m december':'Laatste 12 maanden'} · bedragen excl. btw · houd je muis boven een balk voor het bedrag.</p>`;
}
function renderOrderMap(){
 const rows=state.orders.filter(o=>{if(o.archived)return false;if(orderMapFilter==='all')return true;if(orderMapFilter==='open')return o.stage!=='Afgerond'&&!o.deliveredDate;return o.stage===orderMapFilter;}).map(o=>{
  const t=totals(o),c=customer(o.customerId),index=stages.indexOf(o.stage),color=index<=2?'#7185bf':index<=4?'#d89b32':index<=stages.indexOf('Binnen in Nederland')?'#255ce5':'#2a9978';
  return {id:o.id,number:o.sourceNumber||o.number,customer:c?.company||'Onbekende klant',stage:o.stage,color,waitLabel:o.deliveredDate?'Wachttijd tot levering':'Klant wacht',wait:(elapsed(o.date,o.deliveredDate||today())??'—')+' dagen',amount:euro(t.total),balance:t.balance<0?euro(-t.balance)+' te veel ontvangen':euro(t.balance),...deliveryDetails(o,c)};
 });
 shell(heading('Orderkaart','Alle open orders op één Benelux-kaart.',`<label>Orders tonen<select id="order-map-filter"><option value="open" ${orderMapFilter==='open'?'selected':''}>Alle open orders</option><option value="all" ${orderMapFilter==='all'?'selected':''}>Alle orders (niet gearchiveerd)</option>${stages.map(stage=>`<option value="${esc(stage)}" ${orderMapFilter===stage?'selected':''}>${esc(stage)}</option>`).join('')}</select></label>`)+`<div id="orders-map"></div>`,'order-map');
 renderOrdersMap($('#orders-map'),rows);
}
document.addEventListener('change',e=>{if(e.target.id==='order-map-filter'){orderMapFilter=e.target.value;renderOrderMap();}});

function renderAnalytics(){
 const range=analyticsDateRange(),orders=state.orders.filter(o=>inAnalyticsPeriod(o.date,range));
 const ids=new Set(state.orders.map(o=>o.id)),payments=state.payments.filter(p=>ids.has(p.orderId)&&inAnalyticsPeriod(p.date,range));
 const revenue=orders.reduce((s,o)=>s+totals(o).net,0),cost=orders.reduce((s,o)=>s+economics(o).cost,0),profit=revenue-cost,margin=revenue?profit/revenue*100:0,received=payments.reduce((s,p)=>s+p.amount,0),incomplete=orders.filter(o=>economics(o).provisional).length;
 const customerRows=state.orders.map(o=>({o,t:totals(o)})).filter(x=>x.t.balance>0).sort((a,b)=>b.t.balance-a.t.balance),debtor=customerRows.reduce((s,x)=>s+x.t.balance,0),customerCredit=state.orders.reduce((s,o)=>s+Math.max(0,-totals(o).balance),0);
 const supplierRows=state.purchases.map(p=>{const f=supplierFinance(p);return {p,invoice:f.known?f.total:null,paid:f.paid,balance:f.balance,advance:f.advance};}),creditor=supplierRows.reduce((s,x)=>s+x.balance,0),unknownSuppliers=supplierRows.filter(x=>x.invoice==null).length,supplierAdvance=supplierRows.reduce((s,x)=>s+x.advance,0);
 const stats=[['Orderomzet excl. btw',euro(revenue),`${orders.length} klantorders in de gekozen periode`],['Totale brutomarge',euro(profit),`${margin.toFixed(1)}% · ${incomplete?'voorlopig':'op basis van ingevulde kosten'}`],['Ontvangen klantbetalingen',euro(received),'Op ontvangstdatum · inclusief btw'],['Kostprijs van deze orders',euro(cost),`${incomplete?incomplete+' orders hebben voorlopige cijfers':'Alle kosten ingevuld'}`]];
 const byCustomer=new Map();for(const o of orders){const key=o.customerId,row=byCustomer.get(key)||{id:key,count:0,revenue:0,profit:0,provisional:false};row.count++;row.revenue+=totals(o).net;const e=economics(o);row.profit+=e.profit;row.provisional||=e.provisional;byCustomer.set(key,row);}const top=[...byCustomer.values()].sort((a,b)=>b.revenue-a.revenue).slice(0,8);
 shell(heading('Analytics','Omzet, resultaat en openstaande bedragen.',`<label>Periode<select id="analytics-period"><option value="all" ${analyticsPeriod==='all'?'selected':''}>Alle periodes</option><option value="year" ${analyticsPeriod==='year'?'selected':''}>Dit jaar</option><option value="12months" ${analyticsPeriod==='12months'?'selected':''}>Laatste 12 maanden</option></select></label>`)+`<div class="cards order-stats analytics-stats">${stats.map(([label,value,sub])=>`<div class="card"><span class="muted">${label}</span><strong>${value}</strong><small>${sub}</small></div>`).join('')}</div><p class="analytics-note">Orderomzet is de waarde van geregistreerde orders, inclusief orders in de offertefase; dit is nog geen factuuromzet. Gearchiveerde orders blijven meetellen. ${incomplete?'Ontbrekende kosten zijn nog niet meegenomen in de voorlopige marge.':''}</p><section class="order-surface"><div class="section-heading"><h2>Orderomzet per maand</h2><span class="muted">Exclusief btw</span></div>${analyticsChart(orders,range)}</section><div class="analytics-balances"><section class="order-surface"><div class="section-heading"><div><h2>Debiteuren · te ontvangen</h2><p>Huidig ordersaldo · alle periodes · incl. btw</p></div><strong class="analytics-total">${euro(debtor)}</strong></div>${customerRows.slice(0,12).map(({o,t})=>`<a class="analytics-balance-row" href="#orders/${o.id}"><div><strong>${esc(customer(o.customerId)?.company||'Onbekende klant')}</strong><small>Order #${esc(o.sourceNumber||o.number)}${o.archived?' · gearchiveerd':''}${!o.shippingKnown?' · verzending volgt':''}</small></div><strong>${euro(t.balance)}</strong></a>`).join('')||'<p class="muted">Geen openstaande klantbedragen.</p>'}${customerRows.length>12?`<p class="form-help">${customerRows.length} orders met openstaand saldo. De 12 grootste worden getoond.</p>`:''}${customerCredit?`<p class="form-help">Daarnaast ${euro(customerCredit)} te veel ontvangen van klanten.</p>`:''}</section><section class="order-surface"><div class="section-heading"><div><h2>Crediteuren · te betalen</h2><p>Leveranciersfacturen minus betalingen · alle periodes</p></div><strong class="analytics-total">${euro(creditor)}</strong></div>${unknownSuppliers?`<p class="notice">Voorlopig: bij ${unknownSuppliers} inkoopbestelling${unknownSuppliers===1?'':'en'} ontbreken leveranciersdocumenten of bedragen. Voeg die toe bij Facturen & betalingen. Onbekende documentbedragen zijn niet opgenomen; producten op toekomstige facturen tellen nog niet mee.</p>`:''}${supplierRows.map(({p,invoice,paid,balance})=>`<a class="analytics-balance-row" href="#purchases/${p.id}"><div><strong>${esc(p.supplier||p.name)}</strong><small>${esc(p.name)} · ${invoice==null?'factuurbedrag nog invullen':`factuur ${euro(invoice)} · betaald ${euro(paid)}`}</small></div><strong>${invoice==null?'Voorlopig '+euro(balance):euro(balance)}</strong></a>`).join('')||'<p class="muted">Nog geen inkoopbestellingen.</p>'}${supplierAdvance?`<p class="form-help">Daarnaast ${euro(supplierAdvance)} meer betaald dan het opgegeven leveranciersfactuurbedrag.</p>`:''}<p class="form-help">Dit zijn openstaande bedragen per geregistreerd leveranciersdocument; een overbetaling op één document wordt niet automatisch met een ander verrekend. Verwachte extra facturen, invoerrechten en transportkosten worden niet automatisch een schuld aan die leverancier.</p></section></div><section class="order-surface"><div class="section-heading"><h2>Omzet & marge per klant</h2><span class="muted">Gekozen periode · excl. btw</span></div>${top.map(row=>`<a class="analytics-balance-row" href="#customers/${row.id}"><div><strong>${esc(customer(row.id)?.company||'Onbekende klant')}</strong><small>${row.count} orders${row.provisional?' · marge voorlopig':''}</small></div><div class="analytics-customer-values"><span>Omzet <strong>${euro(row.revenue)}</strong></span><span>Marge <strong>${euro(row.profit)}</strong></span></div></a>`).join('')||'<p class="muted">Nog geen orders in deze periode.</p>'}</section>`,'analytics');
}
document.addEventListener('change',e=>{if(e.target.id==='analytics-period'){analyticsPeriod=e.target.value;renderAnalytics();}});

function selectOrderTab(tab){const id=route()[1];orderView={id,tab};history.replaceState(null,'',`#orders/${id}/${tab}`);renderOrder(id);}

// Local imports run once per page load; active edits are never replaced.
try{
 const imported=runtime.mode==='cloud'?null:await importLocalOrders({db,stages,today:today(),beforeCommit:()=>{if(editingLocally())throw Error('Herlaad na het opslaan om de lokale import over te nemen.');beginLocalStateChange();}});
 if(imported){state=imported.state;state.orders.forEach(syncSingleOrderDelivery);notifyDataChanged();location.hash=imported.route||`orders/${imported.ids.at(-1)}`;render();toast('Lokale gegevens toegevoegd, inclusief documenten en betalingen');}
}catch(error){toast('Lokale import: '+error.message);}

// Startup migrations are not user actions. History starts after they finish.
sessionUndo.enable();refreshUndoButton();
